-- Do not apply to production without a separate schema/policy review.
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.stories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.chapters ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.reading_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.library_entries ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.comments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.echoes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.profiles, public.stories, public.chapters, public.reading_events, public.library_entries, public.comments, public.echoes, public.notifications FROM anon, authenticated;
GRANT SELECT ON public.profiles TO anon, authenticated;
GRANT INSERT (id, username) ON public.profiles TO authenticated;
GRANT UPDATE (username) ON public.profiles TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.stories, public.chapters TO authenticated;
GRANT SELECT ON public.stories, public.chapters TO anon;
GRANT SELECT, INSERT, DELETE ON public.library_entries TO authenticated;
GRANT SELECT ON public.reading_events TO authenticated;
GRANT SELECT, INSERT ON public.comments, public.echoes TO authenticated;
GRANT SELECT, UPDATE ON public.notifications TO authenticated;
DROP POLICY IF EXISTS profiles_public_read ON public.profiles;
DROP POLICY IF EXISTS profiles_insert_self ON public.profiles;
DROP POLICY IF EXISTS profiles_update_self ON public.profiles;
CREATE POLICY profiles_public_read ON public.profiles FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY profiles_insert_self ON public.profiles FOR INSERT TO authenticated WITH CHECK (id = (SELECT auth.uid()) AND role = 'reader');
CREATE POLICY profiles_update_self ON public.profiles FOR UPDATE TO authenticated USING (id = (SELECT auth.uid())) WITH CHECK (id = (SELECT auth.uid()));
DROP POLICY IF EXISTS stories_public_read ON public.stories;
DROP POLICY IF EXISTS stories_author_insert ON public.stories;
DROP POLICY IF EXISTS stories_author_update ON public.stories;
DROP POLICY IF EXISTS stories_author_delete ON public.stories;
CREATE POLICY stories_public_read ON public.stories FOR SELECT TO anon, authenticated USING (status IN ('ongoing','completed') OR author_id = (SELECT auth.uid()));
CREATE POLICY stories_author_insert ON public.stories FOR INSERT TO authenticated WITH CHECK (author_id = (SELECT auth.uid()));
CREATE POLICY stories_author_update ON public.stories FOR UPDATE TO authenticated USING (author_id = (SELECT auth.uid())) WITH CHECK (author_id = (SELECT auth.uid()));
CREATE POLICY stories_author_delete ON public.stories FOR DELETE TO authenticated USING (author_id = (SELECT auth.uid()));
DROP POLICY IF EXISTS chapters_public_read ON public.chapters;
DROP POLICY IF EXISTS chapters_author_insert ON public.chapters;
DROP POLICY IF EXISTS chapters_author_update ON public.chapters;
DROP POLICY IF EXISTS chapters_author_delete ON public.chapters;
CREATE POLICY chapters_public_read ON public.chapters FOR SELECT TO anon, authenticated USING ((is_published = true AND EXISTS (SELECT 1 FROM public.stories s WHERE s.id = chapters.story_id AND s.status IN ('ongoing','completed'))) OR EXISTS (SELECT 1 FROM public.stories s WHERE s.id = chapters.story_id AND s.author_id = (SELECT auth.uid())));
CREATE POLICY chapters_author_insert ON public.chapters FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM public.stories s WHERE s.id = chapters.story_id AND s.author_id = (SELECT auth.uid())));
CREATE POLICY chapters_author_update ON public.chapters FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.stories s WHERE s.id = chapters.story_id AND s.author_id = (SELECT auth.uid()))) WITH CHECK (EXISTS (SELECT 1 FROM public.stories s WHERE s.id = chapters.story_id AND s.author_id = (SELECT auth.uid())));
CREATE POLICY chapters_author_delete ON public.chapters FOR DELETE TO authenticated USING (EXISTS (SELECT 1 FROM public.stories s WHERE s.id = chapters.story_id AND s.author_id = (SELECT auth.uid())));
DROP POLICY IF EXISTS reading_events_read_self ON public.reading_events;
CREATE POLICY reading_events_read_self ON public.reading_events FOR SELECT TO authenticated USING (reader_id = (SELECT auth.uid()));
DROP POLICY IF EXISTS library_entries_read_self ON public.library_entries;
DROP POLICY IF EXISTS library_entries_insert_self ON public.library_entries;
DROP POLICY IF EXISTS library_entries_delete_self ON public.library_entries;
CREATE POLICY library_entries_read_self ON public.library_entries FOR SELECT TO authenticated USING (reader_id = (SELECT auth.uid()));
CREATE POLICY library_entries_insert_self ON public.library_entries FOR INSERT TO authenticated WITH CHECK (reader_id = (SELECT auth.uid()));
CREATE POLICY library_entries_delete_self ON public.library_entries FOR DELETE TO authenticated USING (reader_id = (SELECT auth.uid()));
DROP POLICY IF EXISTS comments_public_read ON public.comments;
DROP POLICY IF EXISTS comments_insert_self ON public.comments;
CREATE POLICY comments_public_read ON public.comments FOR SELECT TO anon, authenticated USING (EXISTS (SELECT 1 FROM public.chapters c JOIN public.stories s ON s.id=c.story_id WHERE c.id=comments.chapter_id AND c.is_published=true AND s.status IN ('ongoing','completed')));
CREATE POLICY comments_insert_self ON public.comments FOR INSERT TO authenticated WITH CHECK (author_id = (SELECT auth.uid()) AND EXISTS (SELECT 1 FROM public.chapters c JOIN public.stories s ON s.id=c.story_id WHERE c.id=comments.chapter_id AND c.is_published=true AND s.status IN ('ongoing','completed')));
DROP POLICY IF EXISTS echoes_read_self ON public.echoes;
DROP POLICY IF EXISTS echoes_insert_self ON public.echoes;
CREATE POLICY echoes_read_self ON public.echoes FOR SELECT TO authenticated USING (reader_id = (SELECT auth.uid()));
CREATE POLICY echoes_insert_self ON public.echoes FOR INSERT TO authenticated WITH CHECK (reader_id = (SELECT auth.uid()) AND EXISTS (SELECT 1 FROM public.chapters c JOIN public.stories s ON s.id=c.story_id WHERE c.id=echoes.chapter_id AND c.is_published=true AND s.status IN ('ongoing','completed')));
DROP POLICY IF EXISTS notifications_read_self ON public.notifications;
DROP POLICY IF EXISTS notifications_update_self ON public.notifications;
CREATE POLICY notifications_read_self ON public.notifications FOR SELECT TO authenticated USING (user_id = (SELECT auth.uid()));
CREATE POLICY notifications_update_self ON public.notifications FOR UPDATE TO authenticated USING (user_id = (SELECT auth.uid())) WITH CHECK (user_id = (SELECT auth.uid()));
REVOKE ALL ON FUNCTION public.stamp_gidireads_catalog_editor() FROM PUBLIC, anon, authenticated;
